const body = $('Webhook').item.json.body
const sessionId = body.sessionId
const message = body.message
const ctx = $input.first().json
const parse = (v) => (typeof v === 'string' ? JSON.parse(v) : v) ?? []
const num = (n) => Number(n ?? 0)
const peso = (n) => '₱' + num(n).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 2 })
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Manila' })

const history = parse(ctx.history).filter(h => h && h.role)
// The new message was stored in the same query that loaded history; keep it out of "so far".
if (history.length && history[history.length - 1].role === 'user' && history[history.length - 1].content === message) history.pop()
const historyText = history.map(h => `${h.role === 'user' ? 'User' : 'Twerp'}: ${h.content}`).join('\n')

const L = []
L.push(`Today is ${today}. All amounts are Philippine pesos.`)
L.push(`Monthly paycheck (income table): ${ctx.income == null ? 'not set' : peso(ctx.income)}.`)
L.push(`This month so far: ${peso(ctx.month_income)} in, ${peso(ctx.month_spent)} out.`)
L.push('')
L.push('ACCOUNTS (id | name | kind)')
for (const a of parse(ctx.accounts)) L.push(`${a.id} | ${a.name} | ${a.kind}`)
L.push('')
L.push('CATEGORIES (id | name | kind)')
for (const c of parse(ctx.categories)) L.push(`${c.id} | ${c.name} | ${c.kind}`)
L.push('')
L.push('BUDGETS (budget id | category | kind | monthly limit | spent this month) - expense = fixed bill, savings = savings target')
for (const b of parse(ctx.budgets)) L.push(`${b.id} | ${b.category} | ${b.kind} | ${peso(b.limit)} | ${peso(b.spent)}`)
L.push('')
L.push('DEBTS (id | name | still owed | borrowed | payment per month | rate % per year | due day)')
const debts = parse(ctx.debts)
if (!debts.length) L.push('none')
for (const d of debts) L.push(`${d.id} | ${d.name} | ${peso(d.balance)} | ${peso(d.original)} | ${peso(d.payment)} | ${num(d.rate)} | ${d.due_day ?? '-'}`)
L.push('')
L.push('RECENT TRANSACTIONS, newest first, last 50 (id | date | amount, negative = spending | category | account | note)')
for (const t of parse(ctx.transactions)) L.push(`${t.id} | ${t.date} | ${num(t.amount)} | ${t.category} | ${t.account} | ${t.note ?? ''}`)
L.push('')
L.push(historyText ? `CONVERSATION SO FAR\n${historyText}` : 'This is the start of the conversation.')
L.push('')
L.push(`USER'S NEW MESSAGE\n${message}`)

// The Agent node runs prompt text through a template where braces are variables.
const prompt = L.join('\n').replace(/[{}]/g, '')
return [{ json: { sessionId, message, today, prompt } }]
